items.example:
const job = await anna.image.generateAwait(
  { prompt: 'art-deco poster of Mars', n: 2, model: 'fal-ai/nano-banana-2',
    aspect_ratio: '9:16', params: { resolution: '4K' },
    clientTag: 'poster-v3', idempotencyKey: `poster-v3:${attempt}` },
  { onProgress: (p) => bar.textContent = `${p.state} · queue ${p.queuePosition ?? '-'}`, signal: ac.signal },
);
for (const im of job.result.images) gallery.add(im.url, im.r2Key);   // url ~30 min; r2Key → image.resign

const job = await anna.image.editAwait({
  image_url: baseUrl, mask_url: maskUrl, prompt: 'replace the sky with aurora',
  model: 'openai/gpt-image-2', params: { quality: 'high' }, idempotencyKey: `edit-${layerId}:${attempt}`,
});

const job = await anna.image.getJob({ jobId });
if (job.state === 'succeeded') render(job.result.images);     // fresh URLs
else if (job.error) toast(`${job.error.code}: ${job.error.message}`);

img.onerror = async () => {
  const { urls } = await anna.image.resign({ r2Keys: [img.dataset.r2Key] });
  img.src = urls[0].url;
};
